// secrets-veil: tree.ts - render tree walker for ui.render overlay
// Generated by OrchestKit mod build

import type { MaskSpan } from "./types";

/**
 * Box properties for render tree nodes.
 */
export interface BoxProps {
  key?: string | number;
  display?: "none" | "flex" | "block" | "inline";
  hover?: { display?: "none" | "flex" | "block" | "inline" };
  border?: boolean;
  borderColor?: string;
  padding?: number;
  flexDirection?: "row" | "column";
}

/**
 * Text properties for render tree nodes.
 */
export interface TextProps {
  children?: string;
  color?: string;
  bold?: boolean;
}

/**
 * A render tree node.
 */
export type RenderNode =
  | { type: "Box"; props?: BoxProps; children?: RenderNode[] }
  | { type: "Text"; props?: TextProps; children?: string }
  | { type: string; props?: Record<string, unknown>; children?: RenderNode[] };

/**
 * Split text into segments based on mask spans, creating a render tree
 * with hover-reveal overlays for each masked segment.
 *
 * Desktop hover semantics (per brief):
 * - A keyed Box with display: none and hover: { display: flex } inside a visible Box
 * - The outer Box stays visible; the inner one reveals on hover
 *
 * @param text - The original text (with secrets)
 * @param spans - Mask spans from mask()
 * @param requestId - The request ID for keying
 * @returns Render tree with secret overlays
 */
export function buildOverlayTree(
  text: string,
  spans: readonly MaskSpan[],
  requestId: string
): RenderNode[] {
  if (spans.length === 0) {
    return [{ type: "Text", props: { children: text } }];
  }

  const nodes: RenderNode[] = [];
  let lastEnd = 0;

  for (let i = 0; i < spans.length; i++) {
    const span = spans[i];

    // Text before this span
    if (span.start > lastEnd) {
      nodes.push({
        type: "Text",
        props: { children: text.slice(lastEnd, span.start) },
      });
    }

    // Masked segment with hover-reveal overlay
    // Key is unique per request+span index
    const key = `veil-${requestId}-${i}`;

    // Per brief: "each span becomes a keyed Box holding Text('......')
    // plus Box({ display: 'none', hover: { display: 'flex' } }, Text(value))"
    const maskedValue = "\u2022".repeat(Math.min(8, span.end - span.start));

    nodes.push({
      type: "Box",
      props: {
        key,
        display: "inline",
      },
      children: [
        // Visible masked text
        {
          type: "Text",
          props: { children: maskedValue },
        },
        // Hidden reveal on hover (Desktop)
        {
          type: "Box",
          props: {
            display: "none",
            hover: { display: "flex" },
          },
          children: [
            {
              type: "Text",
              props: { children: span.value },
            },
          ],
        },
      ],
    });

    lastEnd = span.end;
  }

  // Text after last span
  if (lastEnd < text.length) {
    nodes.push({
      type: "Text",
      props: { children: text.slice(lastEnd) },
    });
  }

  return nodes;
}

/**
 * Walk a render tree and apply masking to all Text leaves.
 * Used for ui.render events where the tree is already built.
 *
 * @param tree - The render tree from next(e)
 * @param spans - Mask spans (positions in the ORIGINAL text)
 * @returns New tree with masked text nodes
 */
export function walkAndMask(
  tree: RenderNode,
  spans: readonly MaskSpan[]
): RenderNode {
  // For simplicity, we rebuild the tree by extracting all text,
  // masking it, and reconstructing.
  // This matches the brief's "walk Text leaves; split on mask spans"

  const fullText = extractText(tree);

  if (spans.length === 0) {
    return tree;
  }

  // For ToolResult/CommandOutput, we need to replace text nodes
  // with overlay nodes. The tree structure from next() is opaque,
  // so we do a text extraction + reconstruction approach.
  return {
    type: "Box",
    props: {},
    children: buildOverlayTree(fullText, spans, "unknown"),
  };
}

/**
 * Extract all text from a render tree.
 */
function extractText(node: RenderNode): string {
  if (node.type === "Text") {
    // The union's catch-all variant makes props a Record<string, unknown> here;
    // Text leaves carry the string in props.children.
    const children = (node.props as TextProps | undefined)?.children;
    return typeof children === "string" ? children : "";
  }
  const children = node.children;
  if (Array.isArray(children)) {
    return children.map(extractText).join("");
  }
  return "";
}

/**
 * Check if a node is a Text node.
 */
export function isTextNode(node: RenderNode): node is { type: "Text"; props?: TextProps } {
  return node.type === "Text";
}

/**
 * Check if a node is a Box node.
 */
export function isBoxNode(node: RenderNode): node is { type: "Box"; props?: BoxProps; children?: RenderNode[] } {
  return node.type === "Box";
}
